import { setUTCHoursForDate } from './setUTCHoursForDate';

describe('setUTCHoursForDate', () => {
  it('should set the UTC hours of a single date', () => {
    const date = new Date('01/01/2022');
    const result = setUTCHoursForDate(date, 12);
    expect(result).toEqual(new Date('2022-01-01T12:00:00Z'));
  });

  it('should set the UTC hours of a date range - only to from', () => {
    const dateRange = {
      from: new Date('01/01/2022'),
      to: undefined,
    };
    const result = setUTCHoursForDate(dateRange);
    expect(result).toEqual({
      from: new Date('2022-01-01T12:00:00Z'),
      to: undefined,
    });
  });

  it('should set the UTC hours of a date range', () => {
    const dateRange = {
      from: new Date('01/01/2022'),
      to: new Date('01/02/2022'),
    };
    const result = setUTCHoursForDate(dateRange);
    expect(result).toEqual({
      from: new Date('2022-01-01T12:00:00Z'),
      to: new Date('2022-01-02T12:00:00Z'),
    });
  });

  it('should set the UTC hours of an array of dates', () => {
    const dates = [new Date('01/01/2022'), new Date('01/02/2022'), new Date('01/03/2022')];
    const result = setUTCHoursForDate(dates, 12);
    expect(result).toEqual([
      new Date('2022-01-01T12:00:00Z'),
      new Date('2022-01-02T12:00:00Z'),
      new Date('2022-01-03T12:00:00Z'),
    ]);
  });

  it('should return undefined for falsy input', () => {
    expect(setUTCHoursForDate(null)).toBeUndefined();
    expect(setUTCHoursForDate(undefined)).toBeUndefined();
    expect(setUTCHoursForDate(false)).toBeUndefined();
    expect(setUTCHoursForDate(0)).toBeUndefined();
    expect(setUTCHoursForDate('')).toBeUndefined();
  });
});
